#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define CLOCK_ID CLOCK_REALTIME

static int signal_count = 0;

// Signal handler function triggered when the timer expires
void timer_handler(int sig, siginfo_t *si, void *uc) {
    if (signal_count < 5) {
        printf("Timer triggered! Count: %d\n", ++signal_count);
    } else {
        // Stop the program after 5 triggers
        printf("Stopping timer and exiting.\n");
        exit(EXIT_SUCCESS);
    }
}

int main(void) {
    timer_t timerid;
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

    // 1. Set up signal handler for SIGRTMIN
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // 2. Specify how the timer should notify (via SIGRTMIN signal)
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timerid; 

    // 3. Create the timer
    if (timer_create(CLOCK_ID, &sev, &timerid) == -1) {
        perror("timer_create");
        return 1;
    }

    // 4. Configure the timer settings (itimerspec)
    // Initial expiration (it_value): 1.5 seconds
    its.it_value.tv_sec = 1;
    its.it_value.tv_nsec = 500000000; 
    // Recurrence interval (it_interval): 0.5 seconds
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 500000000;

    // 5. Arm and start the timer using timer_settime
    printf("Starting periodic timer: Initial=1.5s, Interval=0.5s.\n");
    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        return 1;
    }

    // 6. Wait for signals (indefinitely until the handler exits)
    while(1) {
        pause(); 
    }

    return 0;
}
// Compilation requires linking: gcc program.c -lrt
